              "- Cho HS quan sát tranh động tác.\nTích hợp năng lực số 4.3.CB1a: GV nhắc HS quan sát màn hình ở khoảng cách phù hợp, không xem kéo dài; sau khi xem mẫu chuyển ngay sang luyện tập bài tập phối hợp di chuyển vượt qua chướng ngại vật trên đường thẳng.\n- GV làm mẫu động tác kết hợp phân tích kĩ thuật động tác.\n- Hô khẩu lệnh và thực hiện động tác mẫu\n- Cho 2-3 hs lên thực hiện.\n- GV cùng HS nhận xét, đánh giá tuyên dương\n- GV tổ chức cho HS luyện tập các nội dung dưới hình thức:\n- Luyện tập đồng loạt.\n- GV HD QS chung.\n- GV quan sát sửa sai cho HS.\n- GV mỗi nhóm 1-2 em lên thi đua – trình diễn.\n- GV nhận xét, đánh giá.\n- GV nêu tên trò chơi, hướng dẫn cách chơi cho HS chơi theo trình tự, tổ chức của trò chơi.\n- Cho HS chơi thử và chơi chính thức và phân thắng thua.\n- GV hướng dẫn HS tập.",
              "- Đội hình HS quan sát GV làm mẫu động tác.\nTích hợp: HS biết xem học liệu số trong thời gian ngắn, giữ khoảng cách phù hợp với màn hình và chuyển sang luyện tập bài tập phối hợp di chuyển vượt qua chướng ngại vật trên đường thẳng để bảo vệ sức khỏe.\n- HS quan sát lắng nghe GV chỉ dẫn, nhận xét để vận dụng vào tập luyện\n- Đội hình tập luyện đồng loạt.\n- ĐH tập luyện theo tổ.\n-Thực hiện thi đua giữa các tổ.\n+ HS quan sát bạn trình diễn, đưa ra nhận xét của cá nhân..\nChơi theo hướng dẫn\n\n\n- HS tích cực tham gia trò chơi .\n- Cả lớp tập luyện.\n- HS chạy kết hợp đi lại hít thở"
