          "- Năng lực thể dục thể thao: Biết quan sát tranh ảnh SGK, video/học liệu số hoặc động tác mẫu của GV; biết nhận xét, tự điều chỉnh động tác khi luyện tập động tác chuyền bóng bằng hai tay.",
